def derive(grammar, symbol, choose, max_depth=20, depth=0):
    if symbol not in grammar:
        return [symbol]
    productions = grammar[symbol]
    if not productions:
        raise ValueError(f"{symbol!r} has no productions")
    if depth >= max_depth:
        escapes = [p for p in productions if symbol not in p]
        if not escapes:
            raise RecursionError(
                f"{symbol!r} has no production that avoids itself at the depth cap"
            )
        production = choose(escapes)
    else:
        production = choose(productions)
    out = []
    for part in production:
        out.extend(derive(grammar, part, choose, max_depth, depth + 1))
    return out
